import{_ as o,o as p,c as e,ag as u}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第111章 八周","description":"","frontmatter":{},"headers":[],"relativePath":"第111章_八周.md","filePath":"第111章_八周.md"}'),a={name:"第111章_八周.md"};function _(q,t,r,n,s,c){return p(),e("div",null,[...t[0]||(t[0]=[u('<h1 id="第111章-八周" tabindex="-1">第111章 八周 <a class="header-anchor" href="#第111章-八周" aria-label="Permalink to &quot;第111章 八周&quot;">​</a></h1><p>那年冬天我把那八周摊在桌上。我说，摊在桌上是真的摊在桌上——我打印了，拿公司那台打印机打了十六页纸，左半边是她那边发的，右半边是我这边发的，按日期排，一天一行。</p><p>我为什么要打出来？因为我在屏幕上读了三遍，一直以为在读同一件事，打印出来一张一张并排放，我才看出来那是两件事。</p><p>我先讲头两周。第一周，她在算钱：她那边的记录里全是数字，三千二、两千一、四千七、九百、六十八、四十块、二十八块五，一周发了六十四条，四十一条里有数字。我这周发了八十九条，讲的却是公司那个系统难用、陈树要结婚了、我那个腰又疼了、二月的排班还没出。</p><p>第二周，她在查地方，发了很多张图：一个酒店的外墙，一个换车站，一张公交时间表——她拿手机拍屏，拍糊了又拍一次——一张地图的截图，上面有她画的红线，她把那八天要走的路画了出来。她发过来的时候写了一句：你看我这一圈。</p><p>我这周回的是什么，我读到了：我回的是&quot;那你那两天不是白坐在酒店&quot;。她没回。隔了两天，她自己发了一条别的，把这一页翻过去了。</p><p>第三周，她在置办东西，发了五样要带的东西：一支笔，一本画册，一个眼罩——她说就是那个九块十九个晚上都不压眼睛的，带子松两格，她拿胶布把松出来的那一截粘住了——一张彩铅画的画，画上两个人站在一条路上，背面她写了三个字，说那是唯一一张没卖出去也不打算卖的；一张瓶签上剪下来的小条，她说留了六年，要拿来跟那张凑成一次，为此特意去配了一根绳子。</p><p>我这周在干什么？在跟我一个同事吵架。我在她那边发了四十多条，讲的全是那个同事怎么不讲理。她一条一条回，回的全是&quot;嗯&quot;&quot;那你怎么办&quot;&quot;别理他&quot;&quot;你要不要跟你们领导说&quot;。</p><p>第四周，她在办签证的延期，那天发了一句：我今天在那个大厅排了三个钟头。我说，三个钟头你干什么了。她说，我在算从我的站出来往哪边走。她说，我发现你那个站有两个出口。她说，你不知道哪个出口离你近，你要提前告诉我。我说，我到时候讲。她说，你现在不知道吗。我说，我现在不知道，问了才知道。她说，好，说那问了告诉她。我这周没有问，把这件事放下了。</p><p>第五周，她开始把图交完，每天夜里画到三点，发过来的是画到一半的东西。她说，这张我要带过去给你看。我说，为什么。她说，因为这张我还没画完，画完的那张我不给你看，是要挂出来的。她说，画不完的这张是我这几天的样子。我那天晚上没回。</p><p>我以为我是累了。我今年读到这里才知道不是累，是不敢接——我要是那天回一句&quot;我等这张&quot;，这四天就要开始想二月；要想二月，那天晚上就要承认我在等一个人来，等于我这六年还没到头。我不想还没到头。</p><p>第六周她发了那张订单截图。第七周她开始给我念那个酒店有什么。那周有一天她发了一句很短的话，我没接。她说，我今天跟我姨说我过年回，讲完改口了。我说，为什么改。她说，没什么。我说，那是什么。她说说完&quot;我回&quot;那一下，心里想的是我的城市，不是想我们那个家，怕讲错了重新讲一句&quot;我不回了&quot;；讲完这句她站在厨房里，姨把锅盖上，说&quot;你今年怎么这么多心事&quot;，她说没有。她说，这辈子&quot;没有&quot;这两个字讲得比名字顺。我那天回的是：哦。</p><p>她说，这个酒店房间里有一个水壶，有水壶就不带泡面了；她说，她带了两包纸巾，说我那儿的人吃饭爱洒；她说，她把那张瓶签用绳子系好了；她说，她那天晚上把那个包打好了放在门口，看了三次，说自己这样很像要出远门的小孩。我第七周在干什么？在给一个朋友回一条很长的消息。那个朋友问我到底还打算这样多久，我回他的是：我跟她之间更像是一种我欠她的东西，我更像在赎罪，我要是把这段走完，我就自由了。那三条发出去的时间是那天晚上八点四十一到八点五十七，她那边&quot;我把包打好了放在门口，我看了三次&quot;发在同一天中午十二点四十九。</p><p>第八周有一天，她发了一句很短的话，我今天读出来，坐在椅子上很久。她发的是：你为什么最近不讲二月的事。我说，我讲什么。她说，二月十九号那天我要不要请假。我说，你那个不是定了吗。她说，定了，就是想听我讲一次那天要怎么过。我说，我那天接你，然后吃饭。她说，然后呢。我说，然后你住那家。她说，然后呢。我说，我要讲什么。她说，我要你讲一句你想她，只要一句，她这一个月画图就不难受了。我那天回的是：你想多了。这三个字我发过很多次，今年数出来这十一年跟她讲过二十七次&quot;你想多了&quot;，每一次她讲的都是一句真话。</p><p>那八周里，她在算四件事：钱、地方、要带什么、我那天怎么过；我在算一件事：这段关系什么时候能结清。她二月十九号从那边出发，坐六个钟头的车，换一次公交，走那个我不知道是哪个的出口。那一年二月十九号那天，我在会议室里做汇报，提前两天跟她讲那天要开会，她把票改到二十号，改签花了三百一十块——她那天没有告诉我这三百一十块，我是今年打印这十六页的时候，在她那个&quot;改签成功&quot;的截图底下看见的。</p><p>那八周里，她在攒一次见面，我在看一个结局。</p><p>我今天才知道。</p>',17)])])}const l=o(a,[["render",_]]);export{d as __pageData,l as default};
